  "Mokelumne River - CE Large Floodplain Restoration Project", "https://www.ebmud.com/download_file/force/1093/567?lower_mokelumne_river_spawning_and_rearing_habitat_improvement_project.pdf=", "EBMUD environmental review document for the Lower Mokelumne spawning and rearing habitat program.",
  "Mokelumne River - In Channel Rearing Habitat Restoration Project", "https://www.ebmud.com/download_file/force/1093/567?lower_mokelumne_river_spawning_and_rearing_habitat_improvement_project.pdf=", "EBMUD environmental review document for the Lower Mokelumne spawning and rearing habitat program.",
