projects <- readr::read_csv(input_csv, show_col_types = FALSE) |>
  dplyr::select(project_name, original_description = project_description)

missing_descriptions <- dplyr::anti_join(projects, descriptions, by = "project_name")
unexpected_descriptions <- dplyr::anti_join(descriptions, projects, by = "project_name")
if (nrow(missing_descriptions) > 0 || nrow(unexpected_descriptions) > 0) {
  stop("Project-description entries must match the combined project list exactly.", call. = FALSE)
}

review <- projects |>
  dplyr::left_join(descriptions, by = "project_name") |>
  dplyr::left_join(ceqa_references, by = "project_name") |>
  dplyr::mutate(
    ceqa_note = dplyr::coalesce(
      ceqa_note,
      "No project-specific CEQA record was located during this review; description remains conservative and is supported by the listed project source."
    )
  ) |>
  dplyr::arrange(project_name)

readr::write_csv(review, output_csv, na = "")
message("Wrote ", output_csv)
